window.RP_SESSION={"id":"S-dcafd75f77e3","messages":[{"id":"RP-II-0141313","time":"2026-08-09T14:28:00+09:00","room":"RP II","name":"브로크 그라닐","profile":"Maria Anaïs Ésther","identity":"reviewed","type":"dialogue","body":"햇빛은 쨍 쨍\n\n대모리는...","characters":["P-0605c4d3af71"]},{"id":"RP-II-0141314","time":"2026-08-09T14:28:00+09:00","room":"RP II","name":"브로크 그라닐","profile":"Maria Anaïs Ésther","identity":"reviewed","type":"dialogue","body":"!운명","characters":["P-0605c4d3af71"]},{"id":"RP-II-0141315","time":"2026-08-09T14:28:00+09:00","room":"RP II","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"운명 : 12 = 12\n결과 : 완벽한 성공, 운명은 당신의 편입니다.","characters":[]},{"id":"RP-II-0141316","time":"2026-08-09T14:28:00+09:00","room":"RP II","name":"브로크 그라닐","profile":"Maria Anaïs Ésther","identity":"reviewed","type":"dialogue","body":"뽀송","characters":["P-0605c4d3af71"]},{"id":"RP-II-0141317","time":"2026-08-09T14:29:00+09:00","room":"RP II","name":"브로크 그라닐","profile":"Maria Anaïs Ésther","identity":"reviewed","type":"dialogue","body":"뜨끈뜨끈한 모자를 잠시 벗어두고, 시냇가에서 물 퍼올려 챱챱 바릅니다","characters":["P-0605c4d3af71"]},{"id":"RP-II-0141318","time":"2026-08-09T14:29:00+09:00","room":"RP II","name":"딘","profile":"어설픈 용 ⃢맹","identity":"reviewed","type":"dialogue","body":"\" 선배 좋은 아침 입니다-!! \"\n\n두다다다...\n\n오전부터 러닝 삼매경인 딘은 빠른 인사와 함께 브록을 지나쳐갔습니다.\n\n한 동안 청소와 빨래만 하던 그가, 웬일일까요?","characters":["P-1ebd61bdfafd"]},{"id":"RP-II-0141319","time":"2026-08-09T14:31:00+09:00","room":"RP II","name":"브로크 그라닐","profile":"Maria Anaïs Ésther","identity":"reviewed","type":"dialogue","body":"\"좋은 아침일세 딘군! 오늘따라 더 바빠 보이는구먼?\"\n\n머리에 뭍은 물기를 소매로 닦곤 다시 딘을 바라봤습니다.\n\n\"원래 이 시간이면... 바닥을 쓸고 있지 않았나?\"","characters":["P-0605c4d3af71"]},{"id":"RP-II-0141320","time":"2026-08-09T14:32:00+09:00","room":"RP II","name":"딘","profile":"어설픈 용 ⃢맹","identity":"reviewed","type":"dialogue","body":"\" 네에-!! \"\n\n두다다다... 답변 하나를 남기고 다시 저 멀리 뛰어갑니다.","characters":["P-1ebd61bdfafd"]},{"id":"RP-II-0141321","time":"2026-08-09T14:32:00+09:00","room":"RP II","name":"딘","profile":"어설픈 용 ⃢맹","identity":"reviewed","type":"dialogue","body":"두다다다...\n\n한 바퀴 돌아서 오는군.\n\n\" 결혼하려구요-!! \"\n\n두다다다...\n\n가는군...","characters":["P-1ebd61bdfafd"]},{"id":"RP-II-0141322","time":"2026-08-09T14:34:00+09:00","room":"RP II","name":"브로크 그라닐","profile":"Maria Anaïs Ésther","identity":"reviewed","type":"dialogue","body":"\"?\"\n\n\"흐하하핳!!! 애인이라도 있었나 보군!!\"\n\n재밌는 답에 딘을 뒤뚱뛰뚱 뒤따라 뜁니다","characters":["P-0605c4d3af71"]},{"id":"RP-II-0141323","time":"2026-08-09T14:37:00+09:00","room":"RP II","name":"딘","profile":"어설픈 용 ⃢맹","identity":"reviewed","type":"dialogue","body":"햇볕은 쨍 쨍\n대모리는 뽀송.\n\n그리고 달리기로 땀에 젖은 딘의 얼굴도 반짝입니다.\n\n\" 브록님도...! 헉, 헉 같이 뛰시려구요!? 헉, 헉 \"","characters":["P-1ebd61bdfafd"]},{"id":"RP-II-0141324","time":"2026-08-09T14:38:00+09:00","room":"RP II","name":"브로크 그라닐","profile":"Maria Anaïs Ésther","identity":"reviewed","type":"dialogue","body":"\"맥주를 마시기 전 준비 운동은 필수라네! 엄청난 갈증은 엄청난 맥주를 맛보여준다!!\"\n\n\"그리고 브로크일세!\"","characters":["P-0605c4d3af71"]},{"id":"RP-II-0141325","time":"2026-08-09T14:42:00+09:00","room":"RP II","name":"딘","profile":"어설픈 용 ⃢맹","identity":"reviewed","type":"dialogue","body":"\" 그래요!? 그거 굉장한데요 선배님-!! \"","characters":["P-1ebd61bdfafd"]},{"id":"RP-II-0141326","time":"2026-08-09T14:42:00+09:00","room":"RP II","name":"딘","profile":"어설픈 용 ⃢맹","identity":"reviewed","type":"dialogue","body":"!민첩","characters":["P-1ebd61bdfafd"]},{"id":"RP-II-0141327","time":"2026-08-09T14:42:00+09:00","room":"RP II","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"매칭되는 캐릭터 정보를 찾을 수 없습니다.","characters":[]},{"id":"RP-II-0141328","time":"2026-08-09T14:42:00+09:00","room":"RP II","name":"딘","profile":"어설픈 용 ⃢맹","identity":"reviewed","type":"dialogue","body":"ㅎㅓㄱ","characters":["P-1ebd61bdfafd"]},{"id":"RP-II-0141329","time":"2026-08-09T14:43:00+09:00","room":"RP II","name":"딘","profile":"어설픈 용 ⃢맹","identity":"reviewed","type":"dialogue","body":"!민첩","characters":["P-1ebd61bdfafd"]},{"id":"RP-II-0141330","time":"2026-08-09T14:43:00+09:00","room":"RP II","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"'딘'의 민첩 판정 :\n[10] + [1] = [11]\n결과 : 완벽한 성공, 운명은 당신의 편입니다.","characters":[]},{"id":"RP-II-0141331","time":"2026-08-09T14:43:00+09:00","room":"RP II","name":"딘","profile":"어설픈 용 ⃢맹","identity":"reviewed","type":"dialogue","body":"딘은 달려 나갑니다...!","characters":["P-1ebd61bdfafd"]},{"id":"RP-II-0141332","time":"2026-08-09T14:44:00+09:00","room":"RP II","name":"브로크 그라닐","profile":"Maria Anaïs Ésther","identity":"reviewed","type":"dialogue","body":"!민첩","characters":["P-0605c4d3af71"]},{"id":"RP-II-0141333","time":"2026-08-09T14:44:00+09:00","room":"RP II","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"'Brok Granil'의 민첩 판정 :\n[7] + [0] = [7]\n결과 : 쓰라린 실패, 운명을 빗겨갈 순 없습니다.","characters":[]},{"id":"RP-II-0141334","time":"2026-08-09T14:44:00+09:00","room":"RP II","name":"브로크 그라닐","profile":"Maria Anaïs Ésther","identity":"reviewed","type":"dialogue","body":"\"흐하헣!\"","characters":["P-0605c4d3af71"]},{"id":"RP-II-0141335","time":"2026-08-09T14:45:00+09:00","room":"RP II","name":"브로크 그라닐","profile":"Maria Anaïs Ésther","identity":"reviewed","type":"dialogue","body":"\"헣..헣.....\"\n\n뒤뚱뒤뚱 뒤쫒아갑니다","characters":["P-0605c4d3af71"]},{"id":"RP-II-0141336","time":"2026-08-09T14:45:00+09:00","room":"RP II","name":"브로크 그라닐","profile":"Maria Anaïs Ésther","identity":"reviewed","type":"dialogue","body":"\"날렵하구만..!\"","characters":["P-0605c4d3af71"]},{"id":"RP-II-0141337","time":"2026-08-09T14:47:00+09:00","room":"RP II","name":"브로크 그라닐","profile":"Maria Anaïs Ésther","identity":"reviewed","type":"dialogue","body":"\"대채 핳핳...... 그 여자가 누구길래 그렇, 핳... 게 뛰는가!\"","characters":["P-0605c4d3af71"]},{"id":"RP-II-0141338","time":"2026-08-09T14:50:00+09:00","room":"RP II","name":"딘","profile":"어설픈 용 ⃢맹","identity":"reviewed","type":"dialogue","body":"\" 하핫!! 선배님도 아실런지 모르겠네요!! 들어보셨어요!? 우리 길드에 공주님이 한 분 계시거든요-!! \"\n\n이젠 숨도 차지 않습니다.\n\n아니, 헉헉대면서도 딘의 얼굴은 힘들다기보단 개운해보였습니다.\n\n\" 공주님 이름은... 글로우씨에요!! 스노우, 글로우! \"","characters":["P-1ebd61bdfafd"]},{"id":"RP-II-0141339","time":"2026-08-09T14:53:00+09:00","room":"RP II","name":"브로크 그라닐","profile":"Maria Anaïs Ésther","identity":"reviewed","type":"dialogue","body":"\"하하핳!! 들어본 적 없구먼!\n\n그 여자의 어디가 딘 군을 빠지게 만든 겐가?\"","characters":["P-0605c4d3af71"]},{"id":"RP-II-0141340","time":"2026-08-09T14:56:00+09:00","room":"RP II","name":"딘","profile":"어설픈 용 ⃢맹","identity":"reviewed","type":"dialogue","body":"\" 어제 청혼했어요-!! 그리고, 대차게 까였죠-!! \"\n\n탓탓탓탓, 경쾌한 뜀박질.\n\n햇살은 쨍쨍.\n\n\" 그래서, 오늘 또 청혼하려고요-!! \"\n\n땀방울은 반짝.\n\n\" 내일도, 또 모레도-!! \"","characters":["P-1ebd61bdfafd"]},{"id":"RP-II-0141341","time":"2026-08-09T14:56:00+09:00","room":"RP II","name":"션","profile":"델타인","identity":"reviewed","type":"dialogue","body":"훈련장에서 수강생들을 신나게 두들겨 패고 나오던 션. 그는 생전 처음 보는 광경을 목도합니다.\n\n\"크으아함…. 뭣, 드워프가 죽을 위험이 없는데도 뛰다니.\"","characters":["P-3bbc4a823df9"]},{"id":"RP-II-0141342","time":"2026-08-09T14:56:00+09:00","room":"RP II","name":"션","profile":"델타인","identity":"reviewed","type":"dialogue","body":"\"내일 크아킨이 다시 부활하려나?\"","characters":["P-3bbc4a823df9"]},{"id":"RP-II-0141343","time":"2026-08-09T14:57:00+09:00","room":"RP II","name":"브로크 그라닐","profile":"Maria Anaïs Ésther","identity":"reviewed","type":"dialogue","body":"\"흐하하핳핳!! 언젠가 결혼식에는 꼭 불러주시게나!\"","characters":["P-0605c4d3af71"]},{"id":"RP-II-0141344","time":"2026-08-09T14:58:00+09:00","room":"RP II","name":"브로크 그라닐","profile":"Maria Anaïs Ésther","identity":"reviewed","type":"dialogue","body":"!체력","characters":["P-0605c4d3af71"]},{"id":"RP-II-0141345","time":"2026-08-09T14:58:00+09:00","room":"RP II","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"'Brok Granil'의 체력 판정 :\n[4] + [1] = [5]\n결과 : 쓰라린 실패, 운명을 빗겨갈 순 없습니다.","characters":[]},{"id":"RP-II-0141346","time":"2026-08-09T14:58:00+09:00","room":"RP II","name":"브로크 그라닐","profile":"Maria Anaïs Ésther","identity":"reviewed","type":"dialogue","body":"\"하앟...\"","characters":["P-0605c4d3af71"]},{"id":"RP-II-0141347","time":"2026-08-09T14:58:00+09:00","room":"RP II","name":"션","profile":"델타인","identity":"reviewed","type":"dialogue","body":"\"이봐! 드워프 친구!\"","characters":["P-3bbc4a823df9"]},{"id":"RP-II-0141348","time":"2026-08-09T14:58:00+09:00","room":"RP II","name":"션","profile":"델타인","identity":"reviewed","type":"dialogue","body":"\"자네들은 뛰기보다 구르는 게 빠르다네!\"","characters":["P-3bbc4a823df9"]},{"id":"RP-II-0141349","time":"2026-08-09T14:58:00+09:00","room":"RP II","name":"브로크 그라닐","profile":"Maria Anaïs Ésther","identity":"reviewed","type":"dialogue","body":"찰푸닥 주저앉았습니다","characters":["P-0605c4d3af71"]},{"id":"RP-II-0141350","time":"2026-08-09T14:58:00+09:00","room":"RP II","name":"션","profile":"델타인","identity":"reviewed","type":"dialogue","body":"기묘하게 직접 시켜본 경험이 섞인 듯한 발언….","characters":["P-3bbc4a823df9"]},{"id":"RP-II-0141351","time":"2026-08-09T14:59:00+09:00","room":"RP II","name":"브로크 그라닐","profile":"Maria Anaïs Ésther","identity":"reviewed","type":"dialogue","body":"\"구르다니!하하핳!\"","characters":["P-0605c4d3af71"]},{"id":"RP-II-0141352","time":"2026-08-09T14:59:00+09:00","room":"RP II","name":"딘","profile":"어설픈 용 ⃢맹","identity":"reviewed","type":"dialogue","body":"\" 네에-!! 크~으게 해야죠-!! \n\n아주,\n\n성대하게-!! \"\n\n딘은 펄쩍 뛰며 불끈 쥔 주먹을 하늘 높이 뻗었습니다.\n\n딘...!\n\n부활!!\n\n...딘!!\n\n활! 부!","characters":["P-1ebd61bdfafd"]},{"id":"RP-II-0141353","time":"2026-08-09T14:59:00+09:00","room":"RP II","name":"브로크 그라닐","profile":"Maria Anaïs Ésther","identity":"reviewed","type":"dialogue","body":"\"공대장 자네 들었는가? 딘 군이 푹 빠진 사람이 생겼더구먼\"","characters":["P-0605c4d3af71"]},{"id":"RP-II-0141354","time":"2026-08-09T15:01:00+09:00","room":"RP II","name":"션","profile":"델타인","identity":"reviewed","type":"dialogue","body":"션은 아직 두 사람에게 걸어오고 있습니다.\n\n\"뭐? 딘 군이 푹 찌른 사람이 생겼다고?\"","characters":["P-3bbc4a823df9"]},{"id":"RP-II-0141355","time":"2026-08-09T15:02:00+09:00","room":"RP II","name":"션","profile":"델타인","identity":"reviewed","type":"dialogue","body":"\"뭘로? 칼로? 다른 걸로?\"","characters":["P-3bbc4a823df9"]},{"id":"RP-II-0141356","time":"2026-08-09T15:03:00+09:00","room":"RP II","name":"브로크 그라닐","profile":"Maria Anaïs Ésther","identity":"reviewed","type":"dialogue","body":"\"뭔소리 하는가!! 사랑한다고 사랑!\"\n\n\"결혼 하겠다고 하네! 하하핳!!\"","characters":["P-0605c4d3af71"]},{"id":"RP-II-0141357","time":"2026-08-09T15:04:00+09:00","room":"RP II","name":"션","profile":"델타인","identity":"reviewed","type":"dialogue","body":"\"결혼? 길드원 중에서?\"\n\n브로크가 짧은 다리로 열심히 걸어서 다가오고, 션은 긴 다리로 뚜벅뚜벅 걸어서 열댓 걸음 만에 도달합니다.","characters":["P-3bbc4a823df9"]},{"id":"RP-II-0141358","time":"2026-08-09T15:05:00+09:00","room":"RP II","name":"브로크 그라닐","profile":"Maria Anaïs Ésther","identity":"reviewed","type":"dialogue","body":"\"스노우 글로우라는 아가씨한테 빠진 모양이오~\"","characters":["P-0605c4d3af71"]},{"id":"RP-II-0141359","time":"2026-08-09T15:10:00+09:00","room":"RP II","name":"션","profile":"델타인","identity":"reviewed","type":"dialogue","body":"\"아, 그 엘프 친구 말인가?\"","characters":["P-3bbc4a823df9"]},{"id":"RP-II-0141360","time":"2026-08-09T15:11:00+09:00","room":"RP II","name":"브로크 그라닐","profile":"Maria Anaïs Ésther","identity":"reviewed","type":"dialogue","body":"\"엘프였나? 난 오늘 처음 들어봐서 말일세!\"\n\n\"수락할 때까지 계속 청혼할 거라는 구만\"","characters":["P-0605c4d3af71"]},{"id":"RP-II-0141361","time":"2026-08-09T15:11:00+09:00","room":"RP II","name":"션","profile":"델타인","identity":"reviewed","type":"dialogue","body":"\"밥은 먹고 사는 건지 통 안 보이더만, 딘 군이랑 남들 눈이 띄지 않는 곳에서 그런 관계를 쌓고 있었다니.\"","characters":["P-3bbc4a823df9"]},{"id":"RP-II-0141362","time":"2026-08-09T15:11:00+09:00","room":"RP II","name":"브로크 그라닐","profile":"Maria Anaïs Ésther","identity":"reviewed","type":"dialogue","body":"\"난 딘 군을 믿네~\"","characters":["P-0605c4d3af71"]},{"id":"RP-II-0141363","time":"2026-08-09T15:12:00+09:00","room":"RP II","name":"션","profile":"델타인","identity":"reviewed","type":"dialogue","body":"\"엘프라면 남는 게 시간이니까.\"","characters":["P-3bbc4a823df9"]},{"id":"RP-II-0141364","time":"2026-08-09T15:14:00+09:00","room":"RP II","name":"션","profile":"델타인","identity":"reviewed","type":"dialogue","body":"션이 빙글빙글 도는 딘을 보면서…….\n\n?\n\n\"근데 청혼이랑 달리기랑 무슨 상관 관계가 있지?\"","characters":["P-3bbc4a823df9"]},{"id":"RP-II-0141365","time":"2026-08-09T15:14:00+09:00","room":"RP II","name":"브로크 그라닐","profile":"Maria Anaïs Ésther","identity":"reviewed","type":"dialogue","body":"\"나도 모르네!\"","characters":["P-0605c4d3af71"]},{"id":"RP-II-0141366","time":"2026-08-09T15:14:00+09:00","room":"RP II","name":"브로크 그라닐","profile":"Maria Anaïs Ésther","identity":"reviewed","type":"dialogue","body":"\"마음 단련?\"","characters":["P-0605c4d3af71"]},{"id":"RP-II-0141367","time":"2026-08-09T15:15:00+09:00","room":"RP II","name":"션","profile":"델타인","identity":"reviewed","type":"dialogue","body":"\"아니면 상대 눈에 띄일 때까지 이렇게 계속 배회할 작정인 건가?\"","characters":["P-3bbc4a823df9"]},{"id":"RP-II-0141368","time":"2026-08-09T15:15:00+09:00","room":"RP II","name":"브로크 그라닐","profile":"Maria Anaïs Ésther","identity":"reviewed","type":"dialogue","body":"\"오오!\"","characters":["P-0605c4d3af71"]},{"id":"RP-II-0141369","time":"2026-08-09T15:41:00+09:00","room":"RP II","name":"브로크 그라닐","profile":"Maria Anaïs Ésther","identity":"reviewed","type":"dialogue","body":"딘... 분명 딘이 지칠 때까지 이 브로크는 지켜보았습니다.\n\n'저 결혼식에서의 맥주는 내가 다 털어야겠구먼.'","characters":["P-0605c4d3af71"]},{"id":"RP-II-0141370","time":"2026-08-09T15:41:00+09:00","room":"RP II","name":"브로크 그라닐","profile":"Maria Anaïs Ésther","identity":"reviewed","type":"dialogue","body":"-fin","characters":["P-0605c4d3af71"]},{"id":"RP-II-0141371","time":"2026-08-09T15:41:00+09:00","room":"RP II","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"... 계속.","characters":[]},{"id":"RP-II-0141372","time":"2026-08-09T16:06:00+09:00","room":"RP II","name":"딘","profile":"어설픈 용 ⃢맹","identity":"reviewed","type":"dialogue","body":"H E L L O W , W O R L D !\n\n   T OD AY D EAN .","characters":["P-1ebd61bdfafd"]},{"id":"RP-II-0141373","time":"2026-08-09T16:07:00+09:00","room":"RP II","name":"딘","profile":"어설픈 용 ⃢맹","identity":"reviewed","type":"dialogue","body":"달리기를 마친 딘은 팔굽혀펴기와 윗몸일으키기를 마치고 훈련장 앞에 섭니다.\n\n검과 방패를 쥐고...\n\n\" 핫-!! \"\n\n그간 길드에서 다른 선배들이 훈련하는 모습들.\n\n그리고 숀과 바키르, 티아멧, 션 등 짧막하게 배워 온 검술을 떠올리며...\n\n\" 하압-!! \"","characters":["P-1ebd61bdfafd"]},{"id":"RP-II-0141374","time":"2026-08-09T16:09:00+09:00","room":"RP II","name":"딘","profile":"어설픈 용 ⃢맹","identity":"reviewed","type":"dialogue","body":"숀 선배 검은 더 빨랐어...!\n피에르 선배의 검은 정직하고, 곧았고...!\n그리고 션 대장의 검은 보다 거칠고, 빨랐지...!\n\n\" 이야압-!! \"","characters":["P-1ebd61bdfafd"]},{"id":"RP-II-0141375","time":"2026-08-09T16:11:00+09:00","room":"RP II","name":"딘","profile":"어설픈 용 ⃢맹","identity":"reviewed","type":"dialogue","body":"하지만 난 숀 선배만큼 빠르지도\n피에르 선배만큼 재능 있지도\n션 대장 만큼 크지도 강하지도 않으니...!\n\n\" 얍! 이얍! \"\n\n근성...!\n\n근성이 답이다!!!","characters":["P-1ebd61bdfafd"]},{"id":"RP-II-0141376","time":"2026-08-09T16:11:00+09:00","room":"RP II","name":"딘","profile":"어설픈 용 ⃢맹","identity":"reviewed","type":"dialogue","body":"사진","characters":["P-1ebd61bdfafd"]},{"id":"RP-II-0141377","time":"2026-08-09T16:13:00+09:00","room":"RP II","name":"딘","profile":"어설픈 용 ⃢맹","identity":"reviewed","type":"dialogue","body":"근면, 그리고 성실...!\n\n검이면 검\n활이면 활\n마법이면 마법.\n\n그 어떠한 출중한 재능도 가지지 못한\n언제나 어정쩡한 인물이라는 것.\n\n그것은 딘 스스로 또한 뼈저리게 알고있다...!","characters":["P-1ebd61bdfafd"]},{"id":"RP-II-0141378","time":"2026-08-09T16:14:00+09:00","room":"RP II","name":"딘","profile":"어설픈 용 ⃢맹","identity":"reviewed","type":"dialogue","body":"하지만 범부로 태어났다는 그 이유만으로 범부로 죽어야 하는가!?","characters":["P-1ebd61bdfafd"]},{"id":"RP-II-0141379","time":"2026-08-09T16:15:00+09:00","room":"RP II","name":"딘","profile":"어설픈 용 ⃢맹","identity":"reviewed","type":"dialogue","body":"딘...!\n\n절대범부의 그가 택할 수 있는 것은 언제나 집착이었다!","characters":["P-1ebd61bdfafd"]},{"id":"RP-II-0141380","time":"2026-08-09T16:17:00+09:00","room":"RP II","name":"딘","profile":"어설픈 용 ⃢맹","identity":"reviewed","type":"dialogue","body":"그리고 도서관에서의 부상 이후, 한 동안 그로기 상태에 빠진 절대범부의 가슴 속에...\n\n스노우 글로우라는 불이 번진 것이다...!\n\n아...! 너는 방화범! 나는 숲!\n\n태우리라!\n\n타리라!\n\n\" 타이얏---!! \"","characters":["P-1ebd61bdfafd"]},{"id":"RP-II-0141381","time":"2026-08-09T16:17:00+09:00","room":"RP II","name":"딘","profile":"어설픈 용 ⃢맹","identity":"reviewed","type":"dialogue","body":"!힘","characters":["P-1ebd61bdfafd"]},{"id":"RP-II-0141382","time":"2026-08-09T16:17:00+09:00","room":"RP II","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"'딘'의 힘 판정 :\n[12] + [0] = [12]\n결과 : 완벽한 성공, 운명은 당신의 편입니다.","characters":[]},{"id":"RP-II-0143063","time":"2026-08-10T18:47:00+09:00","room":"RP II","name":"딘","profile":"어설픈 용 ⃢맹","identity":"reviewed","type":"dialogue","body":"\" ... 헉 허억 헉 헉. \"\n\n딘은 뜁니다.\n\n\" 하압-! 하얏-! 타-하앗!! \"\n\n딘은 휘두릅니다.\n\n\" 훕! 훕! 훕...! \"\n\n굽히고, 밉니다.\n\n운동 이틀차.\n\n허벅지는 무겁고, 가슴 근육은 아프고, 팔은 떨립니다.\n\n걸을 때마다 이곳저곳 알싸~한 통증이 함께.\n\n\" 으아아아-!! 아자아자!! 파이틴-!!! \"","characters":["P-1ebd61bdfafd"]},{"id":"RP-II-0143064","time":"2026-08-10T19:09:00+09:00","room":"RP II","name":"마리아 아나이스","profile":"Maria Anaïs Ésther","identity":"reviewed","type":"dialogue","body":"\"아자아자!\"\n\n\"스노우 씨가 보고 있다 생각하고 해 봐요!!\"\n\n구석에서 열심히 박수 쳐줍니다. \n\n짝짝 말고 달그락..","characters":["P-c9505ea97ebc"]},{"id":"RP-II-0143065","time":"2026-08-10T19:26:00+09:00","room":"RP II","name":"딘","profile":"어설픈 용 ⃢맹","identity":"reviewed","type":"dialogue","body":"찡긋!\n\n마리아에게 윙크 한 번.\n\n자, 다시 뛰자!","characters":["P-1ebd61bdfafd"]},{"id":"RP-II-0143066","time":"2026-08-10T19:26:00+09:00","room":"RP II","name":"딘","profile":"어설픈 용 ⃢맹","identity":"reviewed","type":"dialogue","body":"-fin","characters":["P-1ebd61bdfafd"]},{"id":"RP-II-0143067","time":"2026-08-10T19:26:00+09:00","room":"RP II","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"...다음 시간에.","characters":[]},{"id":"RP-II-0143068","time":"2026-08-10T19:51:00+09:00","room":"RP II","name":"브랜","profile":"브랜","identity":"unresolved","type":"dialogue","body":"사진","characters":[]},{"id":"RP-II-0151364","time":"2026-08-13T12:26:00+09:00","room":"RP II","name":"딘","profile":"어설픈 용 ⃢맹","identity":"reviewed","type":"dialogue","body":"딘은...\n\n  뛴다!\n  \n  오늘도!\n\n두 다리가...\n\n  또,\n\n  심장이...!","characters":["P-1ebd61bdfafd"]},{"id":"RP-II-0151365","time":"2026-08-13T12:27:00+09:00","room":"RP II","name":"딘","profile":"어설픈 용 ⃢맹","identity":"reviewed","type":"dialogue","body":"강해지기 위한 노으력.\n\n왜?\n\n무엇을 위해서?\n\n... 그것은 사랑!\n\n한 없이도 강한 나태를 이겨낸 것은...\n\n... 사랑을 위해서!","characters":["P-1ebd61bdfafd"]},{"id":"RP-II-0151366","time":"2026-08-13T12:28:00+09:00","room":"RP II","name":"딘","profile":"어설픈 용 ⃢맹","identity":"reviewed","type":"dialogue","body":"으아아!!!!~~!!!","characters":["P-1ebd61bdfafd"]},{"id":"RP-II-0151367","time":"2026-08-13T12:39:00+09:00","room":"RP II","name":"하일로 조바","profile":"하일로 조바","identity":"reviewed","type":"dialogue","body":"\" ? \"\n\n 오늘도 목검 하나 챙겨서 훈련장으로 나왔습니다... 만?\n\n 먼저 나와서 뛰고 있는 딘이 보이네요. 세상 모르고 열심히 뛰고 있는 딘을 보고 있으니.. 뭔가, 딘에게 집중하게 됩니다.\n\n 그가 요즘 저리 뛰는 건.. 흠, 모르겠네요.","characters":["P-f6ccefd2c259"]},{"id":"RP-II-0151368","time":"2026-08-13T12:52:00+09:00","room":"RP II","name":"딘","profile":"어설픈 용 ⃢맹","identity":"reviewed","type":"dialogue","body":"탓탓탓탓탓탓...","characters":["P-1ebd61bdfafd"]},{"id":"RP-II-0151370","time":"2026-08-13T12:52:00+09:00","room":"RP II","name":"딘","profile":"어설픈 용 ⃢맹","identity":"reviewed","type":"dialogue","body":"그리고, 잠깐 멈칫...!","characters":["P-1ebd61bdfafd"]},{"id":"RP-II-0151371","time":"2026-08-13T12:53:00+09:00","room":"RP II","name":"딘","profile":"어설픈 용 ⃢맹","identity":"reviewed","type":"dialogue","body":"\" 안되겠다. 티아멧 선배에게 물어봐야지. \"","characters":["P-1ebd61bdfafd"]}]};
